// src/pages/MeetingRoom.js

import {
  useLocation,
} from "react-router-dom";

import {
  useState,
  useEffect,
  useRef,
} from "react";

function MeetingRoom() {
  const location = useLocation();

  const roomTitle =
    location.state?.title ||
    "독서모임";

  const [input, setInput] =
    useState("");

  const [messages, setMessages] =
    useState([
      // =========================
      // 처음 입장했을 때만 나오는 AI
      // =========================
      {
        user: "AI",
        type: "ai",
        text:
          "모임원들의 독후감과 기록을 먼저 정리했어요 ✨\n\n• 외로움과 연결감\n• 상실 이후의 성장\n• 잔잔하지만 깊은 감정선\n• 현실적인 인간 관계",
      },

      {
        user: "AI",
        type: "ai",
        text:
          "오늘은 가장 기억에 남았던 문장을 함께 이야기해볼게요 🙂",
      },

      // =========================
      // 기존 더미 참가자
      // =========================
      {
        user: "민지",
        type: "other",
        color: "#FFB6C1",
        text:
          "저는 마지막 장면이 가장 슬펐어요.",
      },

      {
        user: "현우",
        type: "other",
        color: "#87CEEB",
        text:
          "문장이 진짜 고요해서 좋았어요.",
      },

      {
        user: "서연",
        type: "other",
        color: "#C3E88D",
        text:
          "와타나베 감정선이 너무 현실적이었어요.",
      },
    ]);

  const chatEndRef = useRef(null);

  // =========================
  // 새로운 메시지가 생기면
  // 채팅을 아래로 이동
  // =========================

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({
      behavior: "smooth",
    });
  }, [messages]);

  // =========================
  // 일반 채팅 메시지 전송
  // =========================

  const sendMessage = () => {
    if (!input.trim()) return;

    const myMessage = {
      user: "나",
      type: "me",
      text: input.trim(),
    };

    setMessages((prev) => [
      ...prev,
      myMessage,
    ]);

    setInput("");

    // 중요
    // 여기서는 AI가 자동으로 답변하지 않음
  };

  // =========================
  // AI 진행자 호출
  // =========================

  const requestAI = () => {
    // 현재까지의 대화 내용을 정리
    const conversation =
      messages.map((message) => ({
        user: message.user,
        text: message.text,
        type: message.type,
      }));

    // 현재는 백엔드 연결 전이므로
    // 콘솔에서 전달할 데이터를 확인
    console.log(
      "AI에게 전달할 현재 대화:",
      conversation
    );

    // =========================
    // 임시 AI 응답
    // =========================

    const aiReply = {
      user: "AI",
      type: "ai",
      text:
        "좋은 의견들이 나오고 있네요 🌿\n\n지금까지 이야기한 내용을 보면 인물의 감정과 상실에 대한 이야기가 많이 나온 것 같아요.\n\n여러분은 이 책에서 가장 공감했던 인물의 감정이 무엇이었나요?",
    };

    setMessages((prev) => [
      ...prev,
      aiReply,
    ]);
  };

  return (
    <>
      {/* ==================================================
          Meeting Room
      ================================================== */}

      <div className="meeting-page">

        {/* =========================
            상단 헤더
        ========================= */}

        <div className="meeting-header">
          <div>
            <div className="meeting-room-name">
              📚 {roomTitle}
            </div>
          </div>
        </div>

        {/* =========================
            채팅 영역
        ========================= */}

        <div className="meeting-chat-area">

          {messages.map((msg, index) => (
            <div
              key={index}
              className={`chat-row ${
                msg.type === "me"
                  ? "right"
                  : "left"
              }`}
            >

              {/* =========================
                  프로필
              ========================= */}

              {msg.type !== "me" && (
                <div
                  className="chat-profile"
                  style={{
                    background:
                      msg.type === "ai"
                        ? "#9bd44e"
                        : msg.color,
                  }}
                >
                  {msg.user[0]}
                </div>
              )}

              {/* =========================
                  이름 + 말풍선
              ========================= */}

              <div className="chat-content">

                {msg.type !== "me" && (
                  <div className="chat-name">
                    {msg.user}
                  </div>
                )}

                <div
                  className={`chat-bubble ${
                    msg.type === "me"
                      ? "user-chat"
                      : msg.type === "ai"
                      ? "ai-chat"
                      : "other-chat"
                  }`}
                >
                  {msg.text}
                </div>

              </div>
            </div>
          ))}

          <div ref={chatEndRef}></div>

        </div>

        {/* =========================
            AI 진행자 버튼
        ========================= */}

        <div className="ai-request-area">

          <button
            className="ai-request-btn"
            onClick={requestAI}
          >
            ✨ AI 진행자에게 질문하기
          </button>

        </div>

        {/* =========================
            채팅 입력
        ========================= */}

        <div className="meeting-input-wrap">

          <input
            value={input}
            onChange={(e) =>
              setInput(e.target.value)
            }
            placeholder="생각을 입력해보세요"
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                sendMessage();
              }
            }}
          />

          <button
            onClick={sendMessage}
          >
            전송
          </button>

        </div>

      </div>

      {/* ==================================================
          MeetingRoom 전용 CSS
          별도의 MeetingRoom.css 수정 필요 없음
      ================================================== */}

      <style>{`

        /* =========================
           전체 페이지
        ========================= */

        .meeting-page {
          width: 100%;
          max-width: 430px;
          height: 100vh;

          margin: 0 auto;

          display: flex;
          flex-direction: column;

          background: #ffffff;

          box-sizing: border-box;

          overflow: hidden;
        }


        /* =========================
           상단 헤더
        ========================= */

        .meeting-header {
          flex-shrink: 0;

          width: 100%;

          padding: 18px 20px;

          box-sizing: border-box;

          border-bottom: 1px solid #eeeeee;

          background: #ffffff;
        }

        .meeting-room-name {
          font-size: 18px;
          font-weight: 700;

          color: #222222;
        }


        /* =========================
           채팅 영역
        ========================= */

        .meeting-chat-area {
          flex: 1;

          width: 100%;

          padding: 20px 16px 10px;

          box-sizing: border-box;

          overflow-y: auto;
          overflow-x: hidden;

          background: #fafbf8;
        }

        .meeting-chat-area::-webkit-scrollbar {
          width: 5px;
        }

        .meeting-chat-area::-webkit-scrollbar-thumb {
          background: #dddddd;

          border-radius: 999px;
        }


        /* =========================
           채팅 한 줄
        ========================= */

        .chat-row {
          width: 100%;

          display: flex;

          align-items: flex-start;

          gap: 8px;

          margin-bottom: 16px;
        }

        .chat-row.left {
          justify-content: flex-start;
        }

        .chat-row.right {
          justify-content: flex-end;
        }


        /* =========================
           프로필
        ========================= */

        .chat-profile {
          flex-shrink: 0;

          width: 36px;
          height: 36px;

          border-radius: 50%;

          display: flex;
          align-items: center;
          justify-content: center;

          color: #ffffff;

          font-size: 14px;
          font-weight: 700;
        }


        /* =========================
           이름 + 메시지
        ========================= */

        .chat-content {
          max-width: 75%;

          display: flex;
          flex-direction: column;
        }

        .chat-row.right .chat-content {
          align-items: flex-end;
        }

        .chat-name {
          margin-bottom: 5px;

          font-size: 12px;

          color: #777777;
        }


        /* =========================
           채팅 말풍선
        ========================= */

        .chat-bubble {
          max-width: 100%;

          padding: 11px 14px;

          border-radius: 16px;

          font-size: 14px;

          line-height: 1.5;

          white-space: pre-line;

          word-break: break-word;

          box-sizing: border-box;
        }


        /* AI */

        .ai-chat {
          background: #eef7da;

          color: #4f652b;

          border-top-left-radius: 5px;
        }


        /* 다른 참가자 */

        .other-chat {
          background: #ffffff;

          color: #444444;

          border: 1px solid #eeeeee;

          border-top-left-radius: 5px;
        }


        /* 나 */

        .user-chat {
          background: #9bd44e;

          color: #ffffff;

          border-top-right-radius: 5px;
        }


        /* =========================
           AI 진행자 영역
        ========================= */

        .ai-request-area {
          flex-shrink: 0;

          width: 100%;

          padding: 8px 14px;

          box-sizing: border-box;

          background: #ffffff;

          border-top: 1px solid #eeeeee;
        }


        /* =========================
           AI 진행자 버튼
        ========================= */

        .ai-request-btn {
          width: 100%;

          height: 44px;

          border: none;

          border-radius: 15px;

          background: #f1f8df;

          color: #6a8c2f;

          font-size: 14px;

          font-weight: 700;

          cursor: pointer;

          transition:
            background 0.15s ease,
            transform 0.15s ease;
        }

        .ai-request-btn:hover {
          background: #e5f2c7;
        }

        .ai-request-btn:active {
          transform: scale(0.98);
        }


        /* =========================
           입력 영역
        ========================= */

        .meeting-input-wrap {
          flex-shrink: 0;

          width: 100%;

          display: flex;

          align-items: center;

          gap: 8px;

          padding: 10px 14px;

          box-sizing: border-box;

          background: #ffffff;

          border-top: 1px solid #eeeeee;
        }


        /* 입력창 */

        .meeting-input-wrap input {
          flex: 1;

          min-width: 0;

          height: 42px;

          padding: 0 14px;

          box-sizing: border-box;

          border: 1px solid #dddddd;

          border-radius: 14px;

          outline: none;

          font-size: 14px;

          color: #333333;

          background: #fafafa;
        }

        .meeting-input-wrap input:focus {
          border-color: #9bd44e;

          background: #ffffff;
        }


        /* 전송 버튼 */

        .meeting-input-wrap button {
          flex-shrink: 0;

          height: 42px;

          padding: 0 15px;

          border: none;

          border-radius: 14px;

          background: #9bd44e;

          color: #ffffff;

          font-size: 13px;

          font-weight: 700;

          cursor: pointer;
        }

        .meeting-input-wrap button:active {
          transform: scale(0.97);
        }


        /* =========================
           모바일 화면
        ========================= */

        @media (max-width: 430px) {

          .meeting-page {
            width: 100%;
          }

          .meeting-chat-area {
            padding-left: 12px;
            padding-right: 12px;
          }

          .chat-content {
            max-width: 78%;
          }

          .ai-request-area {
            padding-left: 10px;
            padding-right: 10px;
          }

          .meeting-input-wrap {
            padding-left: 10px;
            padding-right: 10px;
          }

        }

      `}</style>
    </>
  );
}

export default MeetingRoom;
